import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

// #12: the customer's discount applies once; the bulk discount applies after it, once.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('customer discount applies once below 10 lines', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount applies once, after the customer discount, from 10 lines', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550); // 10,000 * 0.9 * 0.95
});

test('9 lines get the customer discount only', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100); // 9,000 * 0.9
});

